// Compute daily KPIs with Cross-Channel tracking
const ordersRes = $('R1 — Fetch Yesterday Orders').item.json;
const stockRes = $('R2 — Fetch Low Stock Alerts').item.json;

const orders = ordersRes.data || [];
const stockAlerts = stockRes.data || [];

let revenue = 0;
let orderCount = orders.length;
const statusCounts = {};
const dishSales = {};
const channelBreakdown = {};

for (const o of orders) {
  const attr = o.attributes || o;
  const amount = Number(attr.total_amount || 0);
  revenue += amount;

  const s = attr.status || 'unknown';
  statusCounts[s] = (statusCounts[s] || 0) + 1;

  const chan = attr.customer_channel || 'whatsapp';
  channelBreakdown[chan] = channelBreakdown[chan] || { revenue: 0, orders: 0 };
  channelBreakdown[chan].revenue += amount;
  channelBreakdown[chan].orders += 1;

  const items = attr.order_items?.data || attr.order_items || [];
  for (const item of items) {
    const its = item.attributes || item;
    const label = its.label || 'Unknown';
    dishSales[label] = (dishSales[label] || 0) + Number(its.qty || 1);
  }
}

const topDish = Object.entries(dishSales).sort((a,b) => b[1]-a[1])[0];
const avgBasket = orderCount > 0 ? Math.round(revenue / orderCount) : 0;
const cancelRate = orderCount > 0 ? Math.round(((statusCounts.cancelled || 0) / orderCount) * 100) : 0;

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

return [{ json: {
  date: yesterday.toLocaleDateString('fr-FR'),
  kpis: {
    revenue,
    orderCount,
    avgBasket,
    cancelRate,
    topDish: topDish ? topDish[0] : 'N/A',
    topDishCount: topDish ? topDish[1] : 0,
    statusBreakdown: statusCounts,
    channelBreakdown
  },
  stockAlerts: stockAlerts.map(s => ({
    name: (s.attributes || s).name,
    quantity: (s.attributes || s).quantity,
    unit: (s.attributes || s).unit
  }))
}}];

