const history = $('R6 — Fetch 7D History').item.json.data || [];
const yesterday = $('R3 — Compute Daily KPIs').item.json.kpis.revenue;

// Compute average daily revenue over 7 days
let total = 0;
const days = {};
history.forEach(o => {
  const date = (o.attributes || o).createdAt.split('T')[0];
  days[date] = (days[date] || 0) + Number((o.attributes || o).total_amount || 0);
});

const counts = Object.values(days);
const avg = counts.length > 0 ? counts.reduce((a,b) => a+b, 0) / counts.length : 0;

// Determine yield sentiment
const performance = avg > 0 ? (yesterday / avg) : 1;
let sentiment = 'STABLE';
if (performance < 0.8) sentiment = 'UNDERPERFORMING';
if (performance > 1.2) sentiment = 'PEAKING';

return [{ json: { avg, yesterday, performance, sentiment } }];
